SELECT * FROM workflow_log
WHERE user_id = #{userId}

    AND workflow_name LIKE CONCAT('%', #{workflowName}, '%')


    AND start_time >= #{startTime}


    AND start_time <= #{endTime}

ORDER BY start_time DESC

SELECT workflow_id as workflowId, COUNT(*) as executeCount, AVG(execution_time) as averageExecutionTime, AVG(actual_node_count) as averageNodeCount FROM workflow_log WHERE workflow_id IN
#{id}
GROUP BY workflow_id
